      "reference_solution_cpp": "#include <array>\n#include <cassert>\n#include <iostream>\n#include <string>\n#include <utility>\n#include <vector>\n\nenum class GameStatus { InProgress, XWon, OWon, Draw };\n\nclass CaroBoard {\npublic:\n    static constexpr int kSize = 5;\n    static constexpr int kWinLen = 4;\n\nprivate:\n    std::array<std::array<char, kSize>, kSize> grid_{};\n    int moves_played_ = 0;\n\n    int count_dir(int r, int c, int dr, int dc, char player) const {\n        int cnt = 0;\n        int nr = r + dr;\n        int nc = c + dc;\n        while (in_bounds(nr, nc) && grid_[nr][nc] == player) {\n            ++cnt;\n            nr += dr;\n            nc += dc;\n        }\n        return cnt;\n    }\n\npublic:\n    CaroBoard() {\n        for (auto& row : grid_) {\n            row.fill('.');\n        }\n    }\n\n    static bool in_bounds(int r, int c) {\n        return r >= 0 && r < kSize && c >= 0 && c < kSize;\n    }\n\n    char at(int r, int c) const {\n        assert(in_bounds(r, c));\n        return grid_[r][c];\n    }\n\n    bool is_full() const { return moves_played_ == kSize * kSize; }\n\n    bool place(int r, int c, char player) {\n        if (!in_bounds(r, c) || grid_[r][c] != '.') {\n            return false;\n        }\n        grid_[r][c] = player;\n        ++moves_played_;\n        return true;\n    }\n\n    bool has_four_in_row(int r, int c, char player) const {\n        static constexpr int kDirs[4][2] = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};\n        for (const auto& d : kDirs) {\n            int line = 1 + count_dir(r, c, d[0], d[1], player)\n                         + count_dir(r, c, -d[0], -d[1], player);\n            if (line >= kWinLen) {\n                return true;\n            }\n        }\n        return false;\n    }\n};\n\nclass CaroGame {\n    CaroBoard board_;\n    char current_player_ = 'X';\n    GameStatus status_ = GameStatus::InProgress;\n\npublic:\n    const CaroBoard& board() const { return board_; }\n    char current_player() const { return current_player_; }\n    GameStatus status() const { return status_; }\n\n    bool play_move(int r, int c) {\n        if (status_ != GameStatus::InProgress) {\n            return false;\n        }\n        if (!board_.place(r, c, current_player_)) {\n            return false;\n        }\n        if (board_.has_four_in_row(r, c, current_player_)) {\n            status_ = (current_player_ == 'X') ? GameStatus::XWon : GameStatus::OWon;\n        } else if (board_.is_full()) {\n            status_ = GameStatus::Draw;\n        } else {\n            current_player_ = (current_player_ == 'X') ? 'O' : 'X';\n        }\n        return true;\n    }\n};\n\nclass BoardRenderer {\npublic:\n    static std::string format(const CaroBoard& b) {\n        std::string out;\n        for (int r = 0; r < CaroBoard::kSize; ++r) {\n            for (int c = 0; c < CaroBoard::kSize; ++c) {\n                out.push_back(b.at(r, c));\n            }\n            out.push_back('\\n');\n        }\n        return out;\n    }\n};\n\nint main() {\n    // 1. Move validation & horizontal win for X\n    CaroGame g1;\n    assert(!g1.play_move(-1, 0) && g1.current_player() == 'X');\n    assert(!g1.play_move(5, 2) && g1.current_player() == 'X');\n    assert(g1.play_move(2, 0)); // X\n    assert(!g1.play_move(2, 0) && g1.current_player() == 'O'); // occupied\n    assert(g1.play_move(0, 0)); // O\n    assert(g1.play_move(2, 1)); // X\n    assert(g1.play_move(0, 1)); // O\n    assert(g1.play_move(2, 2)); // X\n    assert(g1.play_move(0, 2)); // O\n    assert(g1.play_move(2, 3)); // X wins horizontally\n    assert(g1.status() == GameStatus::XWon);\n    assert(!g1.play_move(4, 4)); // rejected after game over\n\n    // 2. Vertical win for O\n    CaroGame g2;\n    assert(g2.play_move(0, 0) && g2.play_move(1, 4));\n    assert(g2.play_move(0, 1) && g2.play_move(2, 4));\n    assert(g2.play_move(0, 2) && g2.play_move(3, 4));\n    assert(g2.play_move(4, 0) && g2.play_move(4, 4));\n    assert(g2.status() == GameStatus::OWon);\n\n    // 3. Main diagonal and anti-diagonal wins for X\n    CaroGame g3;\n    assert(g3.play_move(0, 0) && g3.play_move(0, 4));\n    assert(g3.play_move(1, 1) && g3.play_move(1, 4));\n    assert(g3.play_move(2, 2) && g3.play_move(2, 4));\n    assert(g3.play_move(3, 3));\n    assert(g3.status() == GameStatus::XWon);\n\n    CaroGame g4;\n    assert(g4.play_move(0, 4) && g4.play_move(0, 0));\n    assert(g4.play_move(1, 3) && g4.play_move(1, 0));\n    assert(g4.play_move(2, 2) && g4.play_move(2, 0));\n    assert(g4.play_move(3, 1));\n    assert(g4.status() == GameStatus::XWon);\n\n    // 4. Full 5x5 draw board (no 4-in-a-row anywhere)\n    const char* draw_rows[5] = {\n        \"XXOOX\",\n        \"OOXXO\",\n        \"XXOOX\",\n        \"OOXXO\",\n        \"XXOOX\"\n    };\n    std::vector<std::pair<int, int>> xs, os;\n    for (int r = 0; r < 5; ++r) {\n        for (int c = 0; c < 5; ++c) {\n            if (draw_rows[r][c] == 'X') xs.push_back({r, c});\n            else os.push_back({r, c});\n        }\n    }\n    CaroGame g_draw;\n    for (std::size_t i = 0; i < os.size(); ++i) {\n        assert(g_draw.play_move(xs[i].first, xs[i].second));\n        assert(g_draw.play_move(os[i].first, os[i].second));\n    }\n    assert(g_draw.play_move(xs.back().first, xs.back().second));\n    assert(g_draw.status() == GameStatus::Draw);\n    std::string rendered = BoardRenderer::format(g_draw.board());\n    assert(rendered == \"XXOOX\\nOOXXO\\nXXOOX\\nOOXXO\\nXXOOX\\n\");\n\n    std::cout << \"ACT_OOP_CARO_PASS:\" << static_cast<int>(g1.status()) << \",\"\n              << static_cast<int>(g2.status()) << \",\" << static_cast<int>(g_draw.status()) << \"\\n\";\n    return 0;\n}\n",
